window.futvizVista("creacion","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"creacion\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"creacion\"]={\"id\":\"creacion\",\"titulo\":\"Ocasiones a favor y en contra\",\"bajada\":\"A la derecha, m\u00e1s xG a favor; arriba, menos xG en contra. Arriba a la derecha dominan las ocasiones.\",\"pregunta\":\"\u00bfQu\u00e9 equipo domina las ocasiones?\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"xg_fav\",\"label\":\"xG a favor por partido (sin penales)\",\"corto\":\"xG a favor\",\"dec\":2},\"y\":{\"col\":\"xg_con\",\"label\":\"xG en contra por partido (sin penales); menos, arriba\",\"corto\":\"xG en contra\",\"dec\":2,\"invertir\":true},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tr\":\"Dominan las ocasiones\",\"tl\":\"Partidos cerrados\",\"br\":\"Partidos abiertos\",\"bl\":\"Dominan los rivales\"}},\"requiere\":[\"xg_fav\",\"xg_con\"],\"subtitulo\":\"Equipos de las 5 ligas \u00b7 {temporada} \u00b7 por partido, sin penales\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG a favor\",\"ayuda\":\"Ordenados por xG a favor por partido (sin penales)\"},{\"id\":\"y\",\"etiqueta\":\"xG en contra\",\"ayuda\":\"Ordenados por xG en contra por partido (sin penales); menos, arriba: primero los que menos ocasiones conceden\"}],\"queMirar\":\"Compara lo que cada equipo crea con lo que concede, medido en xG por partido y sin penales. El eje horizontal es el xG que genera su ataque y el vertical, el que permite a sus rivales. Este \u00faltimo va al rev\u00e9s: cuanto m\u00e1s arriba, menos xG concede, as\u00ed que arriba a la derecha est\u00e1n los equipos que dominan las ocasiones. Las l\u00edneas est\u00e1n en el promedio de cada eje; el xG cuenta ocasiones, no goles.\",\"insight\":\"creacion\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"]};</script>");